async (page) => {
  // We'll use Node.js to start an HTTP server
  const http = require('http');
  const fs = require('fs');
  const path = require('path');

  const filePath = '/tmp/mcp-workspace/candidate_dashboard.html';
  const PORT = 6060;

  const server = http.createServer((req, res) => {
    // Serve the HTML file for root path
    if (req.url === '/' || req.url === '/candidate_dashboard.html') {
      fs.readFile(filePath, 'utf8', (err, data) => {
        if (err) {
          res.writeHead(404, {'Content-Type': 'text/plain'});
          res.end('File not found');
          return;
        }
        res.writeHead(200, {'Content-Type': 'text/html; charset=utf-8'});
        res.end(data);
      });
    } else {
      res.writeHead(404, {'Content-Type': 'text/plain'});
      res.end('Not found');
    }
  });

  server.listen(PORT, 'localhost', () => {
    console.log(`Server running at http://localhost:${PORT}/`);
  });

  return `Server started on port ${PORT}`;
}
